INSERT INTO periodo(numero,nome,ordem) VALUES(3,'3º período',3) ON CONFLICT(numero) DO NOTHING;
INSERT INTO disciplina(periodo_id,nome,slug,descricao,possui_prova) SELECT id,'Projeto de Ideação de Software','projeto_de_ideacao_de_software','Ideação, Lean Canvas, histórias de usuário, navegação, wireframes e Matriz CSD, com cinco aulas.',FALSE FROM periodo WHERE numero=3 ON CONFLICT(slug) DO NOTHING;
INSERT INTO assunto(disciplina_id,nome,slug,ordem) SELECT id,'Introdução','introducao',1 FROM disciplina WHERE slug='projeto_de_ideacao_de_software' ON CONFLICT(disciplina_id,slug) DO NOTHING;
INSERT INTO material(disciplina_id,assunto_id,titulo,descricao,tipo,referencia_externa,fonte_monitor_virtual) SELECT d.id,a.id,'Aula 1 — Introdução','PDF original conferido; fonte do Monitor Virtual.','SLIDE_AULA','local:materiais_academicos/periodo_03/projeto_de_ideacao_de_software/aula_01_introducao/Aula 01 - Projeto de Ideao de Software.pdf',TRUE FROM disciplina d JOIN assunto a ON a.disciplina_id=d.id AND a.slug='introducao' WHERE d.slug='projeto_de_ideacao_de_software' AND NOT EXISTS(SELECT 1 FROM material m WHERE m.disciplina_id=d.id AND m.referencia_externa='local:materiais_academicos/periodo_03/projeto_de_ideacao_de_software/aula_01_introducao/Aula 01 - Projeto de Ideao de Software.pdf');
